check "PVC db-data is Bound: StorageClass standard, ReadWriteOnce, 1Gi" bash -c "[ \"\$(kubectl --context main -n reports-db get pvc db-data -o jsonpath='{.status.phase} {.spec.storageClassName} {.spec.accessModes[0]} {.spec.resources.requests.storage}')\" = 'Bound standard ReadWriteOnce 1Gi' ]"
check "pod db is Running and writes its append-only file to the PVC" bash -c "pod_ready main db reports-db && kubectl --context main -n reports-db exec db -c redis -- sh -c 'ls /data/appendonlydir' >/dev/null && [ \"\$(kubectl --context main -n reports-db get pod db -o jsonpath='{.spec.volumes[?(@.name==\"data\")].persistentVolumeClaim.claimName}')\" = db-data ]"
check "pod db has a 64Mi in-memory scratch volume at /scratch" bash -c "[ \"\$(kubectl --context main -n reports-db get pod db -o jsonpath='{.spec.volumes[?(@.emptyDir.medium==\"Memory\")].emptyDir.sizeLimit}')\" = 64Mi ] && kubectl --context main -n reports-db exec db -c redis -- sh -c 'grep -q \" /scratch tmpfs\" /proc/mounts'"
